            "target": "table/hooks/use-table-state-handlers.ts",
            "content": "'use client'\n\nimport type {\n  ColumnFiltersState,\n  OnChangeFn,\n  PaginationState,\n  SortingState,\n} from '@tanstack/react-table'\nimport { type Dispatch, type SetStateAction, useCallback } from 'react'\n\ninterface ProTableStateHandlersOptions {\n  setPagination: Dispatch<SetStateAction<PaginationState>>\n  setSorting: Dispatch<SetStateAction<SortingState>>\n  setColumnFilters: Dispatch<SetStateAction<ColumnFiltersState>>\n}\n\nexport function useProTableStateHandlers({\n  setPagination,\n  setSorting,\n  setColumnFilters,\n}: ProTableStateHandlersOptions) {\n  const resetToFirstPage = useCallback(() => {\n    setPagination((current) => ({ ...current, pageIndex: 0 }))\n  }, [setPagination])\n  const handleSortingChange = useCallback<OnChangeFn<SortingState>>(\n    (updater) => {\n      setSorting(updater)\n      resetToFirstPage()\n    },\n    [resetToFirstPage, setSorting],\n  )\n  const handleColumnFiltersChange = useCallback<OnChangeFn<ColumnFiltersState>>(\n    (updater) => {\n      setColumnFilters(updater)\n      resetToFirstPage()\n    },\n    [resetToFirstPage, setColumnFilters],\n  )\n\n  return { handleSortingChange, handleColumnFiltersChange }\n}\n",
