            "target": "table/table/body-row.tsx",
            "content": "import type { Row } from '@tanstack/react-table'\nimport { BodyCell } from './body-cell'\nimport { tableInteractiveRowClassName } from './classes'\nimport { ProTableRowElement } from './elements'\nimport type { ProTablePinnedColumnOffsets } from './pinning'\nimport { SortableRow } from './sortable-row'\n\nexport function BodyRow<TData>({\n  row,\n  dragSort,\n  paddingClass,\n  pinnedOffsets,\n}: {\n  row: Row<TData>\n  dragSort?: boolean\n  paddingClass: string\n  pinnedOffsets: ProTablePinnedColumnOffsets\n}) {\n  const cells = row\n    .getVisibleCells()\n    .map((cell) => (\n      <BodyCell\n        key={cell.id}\n        cell={cell}\n        dragSort={dragSort}\n        paddingClass={paddingClass}\n        pinnedOffsets={pinnedOffsets}\n      />\n    ))\n\n  if (dragSort) {\n    return (\n      <SortableRow row={row} paddingClass={paddingClass}>\n        {cells}\n      </SortableRow>\n    )\n  }\n\n  return (\n    <ProTableRowElement\n      data-state={row.getIsSelected() && 'selected'}\n      className={tableInteractiveRowClassName}\n    >\n      {cells}\n    </ProTableRowElement>\n  )\n}\n",
