            "target": "table/table/content-frame.tsx",
            "content": "import { closestCenter, DndContext } from '@dnd-kit/core'\nimport { ProTableContent, type ProTableContentProps } from './content'\n\nexport function ProTableContentFrame<TData>({\n  proTable,\n  tableOptions,\n  paginationOptions,\n  fullLayout,\n  loading,\n  loadingRows,\n  empty,\n  requestError,\n}: ProTableContentProps<TData>) {\n  if (proTable.dragSortEnabled && !loading) {\n    return (\n      <DndContext\n        sensors={proTable.sensors}\n        collisionDetection={closestCenter}\n        onDragEnd={proTable.handleDragEnd}\n      >\n        <ProTableContent\n          proTable={proTable}\n          tableOptions={tableOptions}\n          paginationOptions={paginationOptions}\n          fullLayout={fullLayout}\n          loading={loading}\n          loadingRows={loadingRows}\n          empty={empty}\n          requestError={requestError}\n        />\n      </DndContext>\n    )\n  }\n\n  return (\n    <ProTableContent\n      proTable={proTable}\n      tableOptions={tableOptions}\n      paginationOptions={paginationOptions}\n      fullLayout={fullLayout}\n      loading={loading}\n      loadingRows={loadingRows}\n      empty={empty}\n      requestError={requestError}\n    />\n  )\n}\n",
