            "target": "table/pagination/navigation.tsx",
            "content": "import { ChevronLeft, ChevronRight, ChevronsLeft, ChevronsRight } from 'lucide-react'\nimport { PaginationContent } from './elements'\nimport { PaginationNavigationControl } from './navigation-control'\nimport { PaginationMobileRange, PaginationPageRange } from './page-range'\nimport type { ProTablePaginationLabels } from './types'\n\ninterface PaginationNavigationProps {\n  current: number\n  pageCount: number\n  pageRange: Array<number | '...'>\n  canPrevious: boolean\n  canNext: boolean\n  labels?: ProTablePaginationLabels\n  onPageChange: (page: number) => void\n  onPrevious: () => void\n  onNext: () => void\n}\n\nexport function PaginationNavigation({\n  current,\n  pageCount,\n  pageRange,\n  canPrevious,\n  canNext,\n  labels,\n  onPageChange,\n  onPrevious,\n  onNext,\n}: PaginationNavigationProps) {\n  return (\n    <PaginationContent>\n      <PaginationNavigationControl\n        disabled={!canPrevious}\n        label={labels?.first ?? 'First page'}\n        onClick={() => onPageChange(1)}\n      >\n        <ChevronsLeft size={14} />\n      </PaginationNavigationControl>\n      <PaginationNavigationControl\n        disabled={!canPrevious}\n        label={labels?.previous ?? 'Previous page'}\n        onClick={onPrevious}\n      >\n        <ChevronLeft size={14} />\n      </PaginationNavigationControl>\n      <PaginationPageRange\n        current={current}\n        pageRange={pageRange}\n        labels={labels}\n        onPageChange={onPageChange}\n      />\n      <PaginationMobileRange current={current} pageCount={pageCount} />\n      <PaginationNavigationControl\n        disabled={!canNext}\n        label={labels?.next ?? 'Next page'}\n        onClick={onNext}\n      >\n        <ChevronRight size={14} />\n      </PaginationNavigationControl>\n      <PaginationNavigationControl\n        disabled={!canNext}\n        label={labels?.last ?? 'Last page'}\n        onClick={() => onPageChange(pageCount)}\n      >\n        <ChevronsRight size={14} />\n      </PaginationNavigationControl>\n    </PaginationContent>\n  )\n}\n",
