            "target": "table/pagination/navigation-link.tsx",
            "content": "import type { ReactNode } from 'react'\nimport { cn } from '@/lib/utils'\nimport { PaginationLink } from './elements'\n\ninterface NavigationLinkProps {\n  active?: boolean\n  disabled?: boolean\n  label: string\n  onClick: () => void\n  children: ReactNode\n}\n\nexport function NavigationLink({\n  active,\n  disabled,\n  label,\n  onClick,\n  children,\n}: NavigationLinkProps) {\n  return (\n    <PaginationLink\n      href=\"#\"\n      size=\"icon\"\n      isActive={active}\n      aria-label={label}\n      aria-disabled={disabled}\n      className={cn(\n        'size-8',\n        active && 'pointer-events-none',\n        disabled && 'pointer-events-none opacity-50',\n      )}\n      onClick={(event) => {\n        event.preventDefault()\n        if (!disabled) onClick()\n      }}\n    >\n      {children}\n    </PaginationLink>\n  )\n}\n",
