            "target": "form/layout/action-buttons.tsx",
            "content": "import { ProButton } from '@/components/pro/base/button'\nimport type {\n  ProFormCancelActionProps,\n  ProFormResetActionProps,\n  ProFormSubmitActionProps,\n} from './action-types'\n\nexport function ProFormCancelButton({\n  options,\n  disabled,\n}: {\n  options: ProFormCancelActionProps\n  disabled: boolean\n}) {\n  if (options.hidden) return null\n\n  return (\n    <ProButton\n      prefix={options.icon}\n      variant={options.variant ?? 'outline'}\n      disabled={options.disabled ?? disabled}\n      onClick={options.onClick}\n    >\n      {options.text ?? 'Cancel'}\n    </ProButton>\n  )\n}\n\nexport function ProFormResetButton({\n  options,\n  disabled,\n}: {\n  options: ProFormResetActionProps\n  disabled: boolean\n}) {\n  if (options.hidden) return null\n\n  return (\n    <ProButton\n      prefix={options.icon}\n      variant={options.variant ?? 'secondary'}\n      disabled={options.disabled ?? disabled}\n      onClick={options.onClick}\n    >\n      {options.text ?? 'Reset'}\n    </ProButton>\n  )\n}\n\nexport function ProFormSubmitButton({\n  options,\n  loading,\n}: {\n  options?: ProFormSubmitActionProps\n  loading: boolean\n}) {\n  if (options?.hidden) return null\n\n  return (\n    <ProButton\n      type=\"submit\"\n      prefix={options?.icon}\n      variant={options?.variant ?? 'default'}\n      loading={loading}\n      disabled={options?.disabled || loading}\n    >\n      {loading ? (options?.submittingText ?? 'Submitting...') : (options?.text ?? 'Submit')}\n    </ProButton>\n  )\n}\n",
