            "target": "form/schema/infer-component.ts",
            "content": "import type { SchemaNode } from './types'\n\nexport function inferSchemaComponent(schema: SchemaNode, isRoot = false) {\n  if (schema.enum) return 'Select'\n\n  switch (schema.type) {\n    case 'string':\n      return 'Input'\n    case 'number':\n    case 'integer':\n      return 'Digit'\n    case 'boolean':\n      return 'Switch'\n    case 'array':\n      return 'ArrayField'\n    case 'void':\n      return schema.properties ? 'ProFormSection' : undefined\n    case 'object':\n      return isRoot ? undefined : 'ObjectField'\n    default:\n      return undefined\n  }\n}\n",
