            "target": "editor/classes.ts",
            "content": "export const editorShellRootClassName = 'min-h-0'\n\nexport const editorShellFrameClassName =\n  'rounded-md border border-input overflow-hidden flex flex-col'\n\nexport const editorContentClassName = 'flex min-h-0'\n\nexport const editorPaneClassName = 'flex-1 min-w-0'\n\nexport const editorPaneLoadingClassName = 'size-full bg-muted animate-pulse'\n\nexport const editorPreviewPaneClassName = 'overflow-auto bg-background h-full'\n\nexport const editorPreviewLoadingClassName = 'p-4 text-sm text-muted-foreground animate-pulse'\n\nexport const editorToolbarClassName =\n  'h-9 justify-between gap-1 border-b border-input bg-background px-2'\n\nexport const editorToolbarLeftClassName = 'h-full min-w-0 gap-1 md:flex-1'\n\nexport const editorToolbarCenterClassName = 'gap-0.5 md:flex-none'\n\nexport const editorToolbarRightClassName = 'gap-0.5'\n\nexport const editorToolbarTitleClassName = 'px-3 text-sm font-medium text-foreground capitalize'\n",
