            "target": "editor/monaco/index.ts",
            "content": "export { applyShadcnTheme, fallbackMonacoTheme } from './theme'\nexport { configureTypescript } from './typescript'\n",
            "highlightedContent": "<pre class=\"no-scrollbar min-w-0 overflow-x-auto overflow-y-auto overscroll-x-contain overscroll-y-auto px-4 py-3.5 outline-none !bg-transparent\" style=\"background-color:#FAFAFA;--shiki-dark-bg:#282c34;color:#383A42;--shiki-dark:#abb2bf\" tabindex=\"0\"><code data-line-numbers=\"\"><span class=\"line\" data-line=\"\"><span style=\"color:#A626A4;--shiki-dark:#C678DD\">export</span><span style=\"color:#383A42;--shiki-dark:#ABB2BF\"> { </span><span style=\"color:#E45649;--shiki-dark:#E06C75\">applyShadcnTheme</span><span style=\"color:#383A42;--shiki-dark:#ABB2BF\">, </span><span style=\"color:#E45649;--shiki-dark:#E06C75\">fallbackMonacoTheme</span><span style=\"color:#383A42;--shiki-dark:#ABB2BF\"> } </span><span style=\"color:#A626A4;--shiki-dark:#C678DD\">from</span><span style=\"color:#50A14F;--shiki-dark:#98C379\"> './theme'</span></span>\n<span class=\"line\" data-line=\"\"><span style=\"color:#A626A4;--shiki-dark:#C678DD\">export</span><span style=\"color:#383A42;--shiki-dark:#ABB2BF\"> { </span><span style=\"color:#E45649;--shiki-dark:#E06C75\">configureTypescript</span><span style=\"color:#383A42;--shiki-dark:#ABB2BF\"> } </span><span style=\"color:#A626A4;--shiki-dark:#C678DD\">from</span><span style=\"color:#50A14F;--shiki-dark:#98C379\"> './typescript'</span></span>\n<span class=\"line\" data-line=\"\"></span></code></pre>"
