            "target": "examples/pro-editor-markdown-demo.tsx",
            "content": "\"use client\"\n\nimport { useState } from \"react\"\nimport { ProEditor } from \"@/registry/new-york-v4/pro/editor/index\"\nimport type { PreviewProps } from \"@/registry/new-york-v4/pro/editor/index\"\nimport { MarkdownViewer } from \"@/registry/new-york-v4/pro/viewer/markdown\"\n\nconst INITIAL = `# Getting Started\n\nWelcome to **ProEditor** — Monaco-powered markdown editing with live preview.\n\n## Features\n\n- Full GFM (GitHub Flavored Markdown) support\n- GitHub Flavored Markdown preview\n- Tables, task lists, and strikethrough\n\n## Example Table\n\n| Prop | Type | Default |\n| --- | --- | --- |\n| value | string | — |\n| onChange | function | — |\n| height | number | 300 |\n\n> Tip: Monaco handles large markdown files with excellent performance.\n`\n\nfunction MarkdownPreview({ content }: PreviewProps) {\n  return <MarkdownViewer content={content} className=\"p-4\" />\n}\n\nexport default function ProEditorMarkdownDemo() {\n  const [value, setValue] = useState(INITIAL)\n\n  return (\n    <div className=\"w-full p-4\">\n      <ProEditor\n        language=\"markdown\"\n        value={value}\n        onChange={setValue}\n        preview={{ component: MarkdownPreview }}\n        height={380}\n      />\n    </div>\n  )\n}\n",
