            "target": "viewer/markdown/types.ts",
            "content": "export type MarkdownTheme = 'light' | 'dark'\nexport type AlertType = 'note' | 'tip' | 'important' | 'warning' | 'caution'\n\nexport type MarkdownNode = {\n  type?: string\n  lang?: string\n  value?: string\n  data?: Record<string, unknown>\n  children?: MarkdownNode[]\n}\n\nexport interface MarkdownViewerProps {\n  content: string\n  theme?: MarkdownTheme\n  className?: string\n  emptyText?: string\n}\n",
