            "target": "base/fields/input/index.tsx",
            "content": "'use client'\n\nimport { forwardRef, useRef } from 'react'\nimport { cn } from '@/lib/utils'\nimport { useComposedRef } from '../../hooks/use-composed-ref'\nimport { FieldClearButton, fieldControlClassName, fieldShellClassName } from '../shared/field'\nimport { type AffixSlot, InputAffix } from './affix'\nimport { inputControlClassName } from './classes'\nimport { shouldShowInputClear } from './clear'\nimport type { InputProps as BaseInputProps } from './types'\nimport { useInputAffix } from './use-input-affix'\n\nexport interface InputProps extends BaseInputProps {\n  prefix?: AffixSlot\n  suffix?: AffixSlot\n  allowClear?: boolean\n  onClear?: () => void\n}\n\nexport type { InputValue } from './types'\n\nconst Input = forwardRef<HTMLInputElement, InputProps>(\n  (\n    {\n      prefix,\n      suffix,\n      allowClear = true,\n      onClear,\n      className,\n      inputClassName,\n      type,\n      value,\n      defaultValue,\n      onChange,\n      disabled,\n      readOnly,\n      ...props\n    },\n    ref,\n  ) => {\n    const inputRef = useRef<HTMLInputElement>(null)\n    const composedRef = useComposedRef(inputRef, ref)\n\n    const {\n      currentValue,\n      displayValue,\n      selectedPrefixValue,\n      selectedSuffixValue,\n      emitValue,\n      handleInputChange,\n      handleAffixSelectChange,\n    } = useInputAffix({\n      prefix,\n      suffix,\n      value,\n      defaultValue,\n      onChange,\n      inputRef,\n    })\n    const showClear = shouldShowInputClear({ allowClear, value: currentValue, disabled, readOnly })\n\n    function handleClear() {\n      onClear?.()\n      emitValue('')\n    }\n\n    return (\n      <div className={cn(fieldShellClassName, className)}>\n        <InputAffix\n          affix={prefix}\n          side=\"prefix\"\n          selectedValue={selectedPrefixValue}\n          disabled={disabled || readOnly}\n          onChange={handleAffixSelectChange}\n        />\n\n        <input\n          ref={composedRef}\n          type={type}\n          data-slot=\"input\"\n          value={displayValue}\n          onChange={handleInputChange}\n          disabled={disabled}\n          readOnly={readOnly}\n          className={cn(inputControlClassName, fieldControlClassName, inputClassName)}\n          {...props}\n        />\n\n        {showClear && <FieldClearButton label=\"Clear input\" onClear={handleClear} />}\n\n        <InputAffix\n          affix={suffix}\n          side=\"suffix\"\n          selectedValue={selectedSuffixValue}\n          disabled={disabled || readOnly}\n          onChange={handleAffixSelectChange}\n        />\n      </div>\n    )\n  },\n)\nInput.displayName = 'Input'\n\nexport { Input }\n",
