            "target": "base/fields/select/index.tsx",
            "content": "'use client'\n\nimport type { MouseEvent } from 'react'\nimport { MultiSelectView } from './multi-select'\nimport { SingleSelectView } from './single-select'\nimport type { SelectProps } from './types'\nimport { useSelect } from './use-select'\n\nexport type { SelectOption, SelectProps } from './types'\n\nexport function Select({\n  value,\n  defaultValue,\n  onChange,\n  placeholder,\n  disabled,\n  required,\n  options,\n  allowClear = false,\n  multiple = false,\n  searchable = false,\n  searchPlaceholder,\n  emptyText = 'No results found.',\n  maxTagCount = 2,\n  size,\n  className,\n  triggerClassName,\n  contentClassName,\n}: SelectProps) {\n  const select = useSelect({ value, defaultValue, onChange, options, multiple })\n  const showClear = allowClear && select.selectedValues.length > 0 && !disabled && !required\n\n  function handleClear(_event: MouseEvent<HTMLButtonElement>) {\n    select.handleChange(undefined)\n  }\n\n  if (multiple || searchable) {\n    return (\n      <MultiSelectView\n        select={select}\n        placeholder={placeholder}\n        disabled={disabled}\n        searchable={searchable}\n        searchPlaceholder={searchPlaceholder}\n        emptyText={emptyText}\n        maxTagCount={maxTagCount}\n        size={size}\n        className={className}\n        triggerClassName={triggerClassName}\n        contentClassName={contentClassName}\n        showClear={showClear}\n        onClear={handleClear}\n      />\n    )\n  }\n\n  return (\n    <SingleSelectView\n      select={select}\n      options={options}\n      placeholder={placeholder}\n      disabled={disabled}\n      required={required}\n      size={size}\n      className={className}\n      triggerClassName={triggerClassName}\n      contentClassName={contentClassName}\n      showClear={showClear}\n      onClear={handleClear}\n    />\n  )\n}\n",
