            "target": "base/fields/select/command-options.tsx",
            "content": "import { Check } from 'lucide-react'\nimport { cn } from '@/lib/utils'\nimport {\n  selectCommandIndicatorClassName,\n  selectCommandIndicatorHiddenClassName,\n  selectCommandIndicatorVisibleClassName,\n} from './classes'\nimport type { SelectOption } from './types'\nimport { SelectOptionContent } from './utils'\n\nexport function getSelectCommandOptions({\n  options,\n  selectedValues,\n  onSelect,\n}: {\n  options?: SelectOption[]\n  selectedValues: string[]\n  onSelect: (value: string) => void\n}) {\n  return (\n    options?.map((option) => {\n      const selected = selectedValues.includes(option.value)\n\n      return {\n        key: option.value,\n        value: option.value,\n        disabled: option.disabled,\n        indicator: (\n          <Check\n            className={cn(\n              selectCommandIndicatorClassName,\n              selected\n                ? selectCommandIndicatorVisibleClassName\n                : selectCommandIndicatorHiddenClassName,\n            )}\n          />\n        ),\n        label: <SelectOptionContent option={option} />,\n        onSelect: () => onSelect(option.value),\n      }\n    }) ?? []\n  )\n}\n",
