            "target": "base/fields/radio/classes.ts",
            "content": "export const radioItemClassName =\n  'aspect-square size-4 shrink-0 rounded-full border border-input text-primary shadow-xs transition-[color,box-shadow] outline-none focus-visible:border-ring focus-visible:ring-[3px] focus-visible:ring-ring/50 disabled:cursor-not-allowed disabled:opacity-50 aria-invalid:border-destructive aria-invalid:ring-destructive/20 dark:bg-input/30 dark:aria-invalid:ring-destructive/40'\n\nexport const radioIndicatorClassName = 'relative flex items-center justify-center'\n\nexport const radioIndicatorIconClassName =\n  'absolute top-1/2 left-1/2 size-2 -translate-x-1/2 -translate-y-1/2 fill-primary'\n\nexport const radioGroupClassName = 'flex flex-col gap-2'\n\nexport const radioOptionRootClassName = 'flex items-start gap-2'\n\nexport const radioLabelClassName = 'grid gap-1 font-normal leading-none'\n\nexport const radioLabelDisabledClassName = 'cursor-not-allowed opacity-50'\n\nexport const radioLabelEnabledClassName = 'cursor-pointer'\n\nexport const radioDescriptionClassName = 'text-xs leading-snug text-muted-foreground'\n",
