            "target": "base/fields/date-picker/types.ts",
            "content": "import type { FieldSize } from '../shared/field'\n\nexport interface DatePickerBaseProps {\n  value?: Date\n  onChange?: (date: Date | undefined) => void\n  disabled?: boolean\n  placeholder?: string\n  dateFormat?: string\n  allowClear?: boolean\n  size?: FieldSize\n  className?: string\n}\n",
            "highlightedContent": "<pre class=\"no-scrollbar min-w-0 overflow-x-auto overflow-y-auto overscroll-x-contain overscroll-y-auto px-4 py-3.5 outline-none !bg-transparent\" style=\"background-color:#FAFAFA;--shiki-dark-bg:#282c34;color:#383A42;--shiki-dark:#abb2bf\" tabindex=\"0\"><code data-line-numbers=\"\"><span class=\"line\" data-line=\"\"><span style=\"color:#A626A4;--shiki-dark:#C678DD\">import</span><span style=\"color:#A626A4;--shiki-dark:#C678DD\"> type</span><span style=\"color:#383A42;--shiki-dark:#ABB2BF\"> { </span><span style=\"color:#E45649;--shiki-dark:#E06C75\">FieldSize</span><span style=\"color:#383A42;--shiki-dark:#ABB2BF\"> } </span><span style=\"color:#A626A4;--shiki-dark:#C678DD\">from</span><span style=\"color:#50A14F;--shiki-dark:#98C379\"> '../shared/field'</span></span>\n<span class=\"line\" data-line=\"\"></span>\n<span class=\"line\" data-line=\"\"><span style=\"color:#A626A4;--shiki-dark:#C678DD\">export</span><span style=\"color:#A626A4;--shiki-dark:#C678DD\"> interface</span><span style=\"color:#C18401;--shiki-dark:#E5C07B\"> DatePickerBaseProps</span><span style=\"color:#383A42;--shiki-dark:#ABB2BF\"> {</span></span>\n<span class=\"line\" data-line=\"\"><span style=\"color:#383A42;--shiki-dark:#E06C75\">  value</span><span style=\"color:#0184BC;--shiki-dark:#C678DD\">?</span><span style=\"color:#0184BC;--shiki-dark:#ABB2BF\">:</span><span style=\"color:#C18401;--shiki-dark:#E5C07B\"> Date</span></span>\n<span class=\"line\" data-line=\"\"><span style=\"color:#4078F2;--shiki-dark:#61AFEF\">  onChange</span><span style=\"color:#0184BC;--shiki-dark:#C678DD\">?</span><span style=\"color:#0184BC;--shiki-dark:#ABB2BF\">:</span><span style=\"color:#383A42;--shiki-dark:#ABB2BF\"> (</span><span style=\"color:#383A42;--shiki-light-font-style:inherit;--shiki-dark:#E06C75;--shiki-dark-font-style:italic\">date</span><span style=\"color:#0184BC;--shiki-dark:#ABB2BF\">:</span><span style=\"color:#C18401;--shiki-dark:#E5C07B\"> Date</span><span style=\"color:#0184BC;--shiki-dark:#ABB2BF\"> |</span><span style=\"color:#0184BC;--shiki-dark:#E5C07B\"> undefined</span><span style=\"color:#383A42;--shiki-dark:#ABB2BF\">) </span><span style=\"color:#A626A4;--shiki-dark:#C678DD\">=></span><span style=\"color:#0184BC;--shiki-dark:#E5C07B\"> void</span></span>\n<span class=\"line\" data-line=\"\"><span style=\"color:#383A42;--shiki-dark:#E06C75\">  disabled</span><span style=\"color:#0184BC;--shiki-dark:#C678DD\">?</span><span style=\"color:#0184BC;--shiki-dark:#ABB2BF\">:</span><span style=\"color:#0184BC;--shiki-dark:#E5C07B\"> boolean</span></span>\n<span class=\"line\" data-line=\"\"><span style=\"color:#383A42;--shiki-dark:#E06C75\">  placeholder</span><span style=\"color:#0184BC;--shiki-dark:#C678DD\">?</span><span style=\"color:#0184BC;--shiki-dark:#ABB2BF\">:</span><span style=\"color:#0184BC;--shiki-dark:#E5C07B\"> string</span></span>\n<span class=\"line\" data-line=\"\"><span style=\"color:#383A42;--shiki-dark:#E06C75\">  dateFormat</span><span style=\"color:#0184BC;--shiki-dark:#C678DD\">?</span><span style=\"color:#0184BC;--shiki-dark:#ABB2BF\">:</span><span style=\"color:#0184BC;--shiki-dark:#E5C07B\"> string</span></span>\n<span class=\"line\" data-line=\"\"><span style=\"color:#383A42;--shiki-dark:#E06C75\">  allowClear</span><span style=\"color:#0184BC;--shiki-dark:#C678DD\">?</span><span style=\"color:#0184BC;--shiki-dark:#ABB2BF\">:</span><span style=\"color:#0184BC;--shiki-dark:#E5C07B\"> boolean</span></span>\n<span class=\"line\" data-line=\"\"><span style=\"color:#383A42;--shiki-dark:#E06C75\">  size</span><span style=\"color:#0184BC;--shiki-dark:#C678DD\">?</span><span style=\"color:#0184BC;--shiki-dark:#ABB2BF\">:</span><span style=\"color:#C18401;--shiki-dark:#E5C07B\"> FieldSize</span></span>\n<span class=\"line\" data-line=\"\"><span style=\"color:#383A42;--shiki-dark:#E06C75\">  className</span><span style=\"color:#0184BC;--shiki-dark:#C678DD\">?</span><span style=\"color:#0184BC;--shiki-dark:#ABB2BF\">:</span><span style=\"color:#0184BC;--shiki-dark:#E5C07B\"> string</span></span>\n<span class=\"line\" data-line=\"\"><span style=\"color:#383A42;--shiki-dark:#ABB2BF\">}</span></span>\n<span class=\"line\" data-line=\"\"></span></code></pre>"
