            "target": "base/fields/time-picker/time-part-select.tsx",
            "content": "import { cn } from '@/lib/utils'\nimport {\n  FieldSelect,\n  FieldSelectContent,\n  FieldSelectItem,\n  FieldSelectTrigger,\n  FieldSelectValue,\n} from '../shared/select'\nimport type { TimePartSelectProps } from './types'\nimport { padTimePart } from './utils'\n\nexport function TimePartSelect({\n  value,\n  options,\n  disabled,\n  triggerClassName,\n  onChange,\n}: TimePartSelectProps) {\n  return (\n    <FieldSelect\n      value={String(value)}\n      disabled={disabled}\n      onValueChange={(next) => onChange(Number(next))}\n    >\n      <FieldSelectTrigger\n        className={cn(\n          'h-7 w-12 border-0 bg-transparent px-1 shadow-none focus-visible:ring-0 dark:bg-transparent dark:hover:bg-transparent',\n          triggerClassName,\n        )}\n      >\n        <FieldSelectValue />\n      </FieldSelectTrigger>\n      <FieldSelectContent>\n        {options.map((option) => (\n          <FieldSelectItem key={option} value={String(option)}>\n            {padTimePart(option)}\n          </FieldSelectItem>\n        ))}\n      </FieldSelectContent>\n    </FieldSelect>\n  )\n}\n",
