            "target": "base/fields/digit-range/classes.ts",
            "content": "export const digitRangeRootClassName = 'flex items-center gap-2'\n\nexport const digitRangeInputClassName = 'flex-1'\n\nexport const digitRangeSeparatorClassName = 'shrink-0 text-muted-foreground'\n",
            "highlightedContent": "<pre class=\"no-scrollbar min-w-0 overflow-x-auto overflow-y-auto overscroll-x-contain overscroll-y-auto px-4 py-3.5 outline-none !bg-transparent\" style=\"background-color:#FAFAFA;--shiki-dark-bg:#282c34;color:#383A42;--shiki-dark:#abb2bf\" tabindex=\"0\"><code data-line-numbers=\"\"><span class=\"line\" data-line=\"\"><span style=\"color:#A626A4;--shiki-dark:#C678DD\">export</span><span style=\"color:#A626A4;--shiki-dark:#C678DD\"> const</span><span style=\"color:#986801;--shiki-dark:#E5C07B\"> digitRangeRootClassName</span><span style=\"color:#0184BC;--shiki-dark:#56B6C2\"> =</span><span style=\"color:#50A14F;--shiki-dark:#98C379\"> 'flex items-center gap-2'</span></span>\n<span class=\"line\" data-line=\"\"></span>\n<span class=\"line\" data-line=\"\"><span style=\"color:#A626A4;--shiki-dark:#C678DD\">export</span><span style=\"color:#A626A4;--shiki-dark:#C678DD\"> const</span><span style=\"color:#986801;--shiki-dark:#E5C07B\"> digitRangeInputClassName</span><span style=\"color:#0184BC;--shiki-dark:#56B6C2\"> =</span><span style=\"color:#50A14F;--shiki-dark:#98C379\"> 'flex-1'</span></span>\n<span class=\"line\" data-line=\"\"></span>\n<span class=\"line\" data-line=\"\"><span style=\"color:#A626A4;--shiki-dark:#C678DD\">export</span><span style=\"color:#A626A4;--shiki-dark:#C678DD\"> const</span><span style=\"color:#986801;--shiki-dark:#E5C07B\"> digitRangeSeparatorClassName</span><span style=\"color:#0184BC;--shiki-dark:#56B6C2\"> =</span><span style=\"color:#50A14F;--shiki-dark:#98C379\"> 'shrink-0 text-muted-foreground'</span></span>\n<span class=\"line\" data-line=\"\"></span></code></pre>"
