            "target": "base/fields/rate/index.tsx",
            "content": "'use client'\n\nimport { useId, useState } from 'react'\nimport { cn } from '@/lib/utils'\nimport { rateRootClassName } from './classes'\nimport { RateStar } from './star'\nimport type { RateProps } from './types'\n\nexport type { RateProps } from './types'\n\nexport function Rate({\n  value = 0,\n  onChange,\n  count = 5,\n  disabled,\n  className,\n  'aria-label': ariaLabel = 'Rating',\n}: RateProps) {\n  const id = useId()\n  const [hovered, setHovered] = useState<number | null>(null)\n  const display = hovered ?? value\n\n  return (\n    <div className={cn(rateRootClassName, className)} role=\"radiogroup\" aria-label={ariaLabel}>\n      {Array.from({ length: count }, (_, i) => {\n        const star = i + 1\n\n        return (\n          <RateStar\n            key={star}\n            name={id}\n            value={star}\n            checked={value === star}\n            active={star <= display}\n            disabled={disabled}\n            onChange={onChange}\n            onHover={setHovered}\n          />\n        )\n      })}\n    </div>\n  )\n}\n",
