            "target": "base/fields/captcha/sms/index.tsx",
            "content": "'use client'\n\nimport { useCountdown } from '../../../hooks/use-countdown'\nimport { Input } from '../../input'\nimport { CaptchaSendButton } from './send-button'\nimport type { CaptchaProps } from './types'\n\nexport type { CaptchaProps } from './types'\n\nexport function Captcha({\n  value,\n  onChange,\n  onSend,\n  buttonText = 'Get code',\n  countdown = 60000,\n  placeholder = 'Enter captcha',\n  disabled,\n  className,\n  inputClassName,\n  buttonClassName,\n  suffix,\n  autoComplete,\n  ...inputProps\n}: CaptchaProps) {\n  const { remaining, running, start } = useCountdown({ duration: countdown })\n\n  async function handleSend() {\n    await onSend?.()\n    start()\n  }\n\n  return (\n    <Input\n      {...inputProps}\n      value={value}\n      onChange={onChange}\n      placeholder={placeholder}\n      disabled={disabled}\n      className={className}\n      inputClassName={inputClassName}\n      autoComplete={autoComplete ?? 'off'}\n      suffix={[\n        suffix,\n        <CaptchaSendButton\n          key=\"captcha-action\"\n          disabled={disabled || running}\n          countingDown={running}\n          remaining={remaining}\n          text={buttonText}\n          className={buttonClassName}\n          onClick={() => void handleSend()}\n        />,\n      ]}\n    />\n  )\n}\n",
