            "target": "base/fields/captcha/visual/index.tsx",
            "content": "'use client'\n\nimport { Input } from '../../input'\nimport type { VisualCaptchaProps } from './types'\nimport { CaptchaVisualAddon } from './visual-addon'\n\nexport type { VisualCaptchaProps } from './types'\n\nexport function VisualCaptcha({\n  value,\n  onChange,\n  onRefresh,\n  captchaUrl,\n  captchaText,\n  placeholder = 'Enter captcha',\n  disabled,\n  className,\n  inputClassName,\n  suffix,\n  autoComplete,\n  ...inputProps\n}: VisualCaptchaProps) {\n  return (\n    <Input\n      {...inputProps}\n      value={value}\n      onChange={onChange}\n      placeholder={placeholder}\n      disabled={disabled}\n      className={className}\n      inputClassName={inputClassName}\n      autoComplete={autoComplete ?? 'off'}\n      suffix={[\n        suffix,\n        <CaptchaVisualAddon\n          key=\"captcha-visual\"\n          url={captchaUrl}\n          text={captchaText}\n          disabled={disabled}\n          onRefresh={onRefresh}\n        />,\n      ]}\n    />\n  )\n}\n",
