            "target": "base/fields/money/types.ts",
            "content": "import type { InputProps } from '../input'\n\nexport interface MoneyProps extends Omit<InputProps, 'value' | 'defaultValue' | 'onChange'> {\n  value?: number\n  onChange?: (value: number | undefined) => void\n  currency?: string\n  precision?: number\n}\n",
