            "content": "\"use client\"\n\nimport { createForm } from \"@formily/core\"\nimport { Field, FormProvider } from \"@formily/react\"\n\nimport { FormItem } from \"@/registry/new-york-v4/pro/form/form-item\"\nimport { FormilySlider } from \"@/registry/new-york-v4/pro/form/formily-fields\"\n\nconst form = createForm()\n\nexport default function ProFieldsSliderDemo() {\n  return (\n    <FormProvider form={form}>\n      <div className=\"w-full max-w-sm space-y-6 p-4\">\n        <Field\n          name=\"volume\"\n          title=\"Volume\"\n          initialValue={40}\n          decorator={[FormItem]}\n          component={[\n            FormilySlider,\n            { min: 0, max: 100, step: 1, showValue: true },\n          ]}\n        />\n        <Field\n          name=\"opacity\"\n          title=\"Opacity\"\n          initialValue={70}\n          decorator={[FormItem]}\n          component={[\n            FormilySlider,\n            { min: 0, max: 100, step: 10, showValue: true },\n          ]}\n        />\n        <Field\n          name=\"disabled\"\n          title=\"Disabled\"\n          initialValue={30}\n          decorator={[FormItem]}\n          component={[\n            FormilySlider,\n            { min: 0, max: 100, disabled: true, showValue: true },\n          ]}\n        />\n      </div>\n    </FormProvider>\n  )\n}\n",
