            "target": "base/fields/tree-select/classes.ts",
            "content": "export const treeSelectContentClassName = 'w-64 p-1'\n\nexport const treeSelectListClassName = 'max-h-56 overflow-y-auto'\n\nexport const treeSelectNodeClassName = 'flex items-center gap-1.5 rounded-sm px-2 py-1 text-sm'\n\nexport const treeSelectNodeDisabledClassName = 'cursor-not-allowed opacity-50'\n\nexport const treeSelectNestedListClassName = 'pl-4'\n\nexport const treeSelectExpandPlaceholderClassName = 'size-6 shrink-0'\n\nexport const treeSelectExpandButtonClassName = 'shrink-0'\n\nexport const treeSelectMultipleOptionClassName =\n  'h-auto flex-1 cursor-pointer justify-start rounded-sm px-1 py-0 text-left disabled:cursor-not-allowed'\n\nexport const treeSelectSingleOptionClassName =\n  'h-auto flex-1 cursor-pointer justify-between rounded-sm px-1 py-0.5 text-left disabled:cursor-not-allowed'\n\nexport const treeSelectOptionSelectedClassName = 'font-medium'\n\nexport const treeSelectCheckIconClassName = 'size-3.5 text-primary'\n",
