            "target": "examples/pro-fields-captcha-demo.tsx",
            "content": "\"use client\"\n\nimport { createForm } from \"@formily/core\"\nimport { Field, FormProvider } from \"@formily/react\"\n\nimport { FormItem } from \"@/registry/new-york-v4/pro/form/form-item\"\nimport { FormilyCaptcha } from \"@/registry/new-york-v4/pro/form/formily-fields\"\n\nconst form = createForm()\n\nexport default function ProFieldsCaptchaDemo() {\n  return (\n    <FormProvider form={form}>\n      <div className=\"w-full max-w-sm space-y-6 p-4\">\n        <Field\n          name=\"captcha\"\n          title=\"Captcha\"\n          decorator={[FormItem]}\n          component={[\n            FormilyCaptcha,\n            {\n              placeholder: \"Enter verification code\",\n              buttonText: \"Send code\",\n              countdown: 30000,\n              onSend: () => {},\n            },\n          ]}\n        />\n      </div>\n    </FormProvider>\n  )\n}\n",
