            "content": "import type { MouseEvent } from 'react'\nimport { ProButton } from '@/components/pro/base/button'\n\nexport interface CaptchaSendButtonProps {\n  disabled?: boolean\n  countingDown?: boolean\n  remaining: number\n  text: string\n  className?: string\n  onClick: () => void\n}\n\nexport function CaptchaSendButton({\n  disabled,\n  countingDown,\n  remaining,\n  text,\n  className,\n  onClick,\n}: CaptchaSendButtonProps) {\n  return (\n    <ProButton\n      type=\"button\"\n      variant=\"ghost\"\n      size=\"sm\"\n      disabled={disabled || countingDown}\n      onClick={(event: MouseEvent<HTMLButtonElement>) => {\n        event.stopPropagation()\n        onClick()\n      }}\n      className={className}\n    >\n      {countingDown ? `${Math.ceil(remaining / 1000)}s` : text}\n    </ProButton>\n  )\n}\n",
